"""Magnitude landscapes generated by poles and zeros.

For each transfer function, the animation shows:

1. the pole-zero map;
2. the ordinary magnitude |H(s)|;
3. the distance interpretation;
4. the transformation to 20 log10 |H(s)|;
5. the imaginary-axis slice corresponding to the Bode magnitude;
6. a final viewpoint emphasizing that intersection.

Preview:

    manim -pql modulus_landscapes.py ModulusGraphRealZero

High quality:

    manim -pqh modulus_landscapes.py ModulusGraphGenericTF

Render every scene:

    manim -pqh -a modulus_landscapes.py
"""

from manim import *
import numpy as np


# ---------------------------------------------------------------------------
# Shared parameters
# ---------------------------------------------------------------------------

DOMAIN_MIN = -3.0
DOMAIN_MAX = 3.0

DB_MIN = -30.0
DB_MAX = 20.0

EPSILON = 1e-6
SURFACE_RESOLUTION = 49

ZERO_COLOR = BLUE_C
POLE_COLOR = ORANGE
SLICE_COLOR = YELLOW_C
SAMPLE_COLOR = PINK
SURFACE_COLOR_1 = RED_D
SURFACE_COLOR_2 = RED_E


class MagnitudeLandscapeMixin:
    """Shared implementation used by all the scenes."""

    scene_title = "Magnitude landscape"
    formula = r"H(s)"

    zeros = ()
    poles = ()
    gain = 1.0

    linear_max = 6.0
    sample_start = 1.7 - 1.7j

    # -----------------------------------------------------------------------
    # Magnitude functions
    # -----------------------------------------------------------------------

    def magnitude(self, sigma, omega):
        s = complex(sigma, omega)
        value = abs(self.gain)

        for zero in self.zeros:
            value *= abs(s - zero)

        for pole in self.poles:
            value /= max(
                abs(s - pole),
                EPSILON,
            )

        return value

    def linear_magnitude_clipped(self, sigma, omega):
        return float(
            np.clip(
                self.magnitude(sigma, omega),
                0,
                self.linear_max,
            )
        )

    def db_magnitude_clipped(self, sigma, omega):
        magnitude = max(
            self.magnitude(sigma, omega),
            EPSILON,
        )

        magnitude_db = 20.0 * np.log10(magnitude)

        return float(
            np.clip(
                magnitude_db,
                DB_MIN,
                DB_MAX,
            )
        )

    def target_sample(self):
        """Choose a point close to one zero or pole."""

        if self.zeros:
            factor = self.zeros[0]
        elif self.poles:
            factor = self.poles[0]
        else:
            factor = 0

        return factor + 0.28 + 0.18j

    # -----------------------------------------------------------------------
    # Markers
    # -----------------------------------------------------------------------

    @staticmethod
    def zero_marker(axes, zero):
        marker = Circle(
            radius=0.105,
            color=ZERO_COLOR,
            stroke_width=4,
        )

        marker.move_to(
            axes.c2p(
                zero.real,
                zero.imag,
                0,
            )
        )

        return marker

    @staticmethod
    def pole_marker(axes, pole):
        delta = 0.12

        return VGroup(
            Line(
                axes.c2p(
                    pole.real - delta,
                    pole.imag - delta,
                    0,
                ),
                axes.c2p(
                    pole.real + delta,
                    pole.imag + delta,
                    0,
                ),
                color=POLE_COLOR,
                stroke_width=4,
            ),
            Line(
                axes.c2p(
                    pole.real - delta,
                    pole.imag + delta,
                    0,
                ),
                axes.c2p(
                    pole.real + delta,
                    pole.imag - delta,
                    0,
                ),
                color=POLE_COLOR,
                stroke_width=4,
            ),
        )

    def make_legend(self):
        entries = []

        if self.zeros:
            zero_symbol = Circle(
                radius=0.075,
                color=ZERO_COLOR,
                stroke_width=3,
            )

            zero_entry = VGroup(
                zero_symbol,
                Tex("zero").scale(0.42),
            ).arrange(RIGHT, buff=0.08)

            entries.append(zero_entry)

        if self.poles:
            pole_symbol = VGroup(
                Line(
                    UL * 0.075,
                    DR * 0.075,
                    color=POLE_COLOR,
                    stroke_width=3,
                ),
                Line(
                    DL * 0.075,
                    UR * 0.075,
                    color=POLE_COLOR,
                    stroke_width=3,
                ),
            )

            pole_entry = VGroup(
                pole_symbol,
                Tex("pole").scale(0.42),
            ).arrange(RIGHT, buff=0.08)

            entries.append(pole_entry)

        return VGroup(*entries).arrange(
            RIGHT,
            buff=0.28,
        )

    # -----------------------------------------------------------------------
    # Main animation
    # -----------------------------------------------------------------------

    def construct(self):

        # ---------------------------------------------------------------
        # Linear and logarithmic coordinate systems
        # ---------------------------------------------------------------

        linear_axes = ThreeDAxes(
            x_range=[DOMAIN_MIN, DOMAIN_MAX, 1],
            y_range=[DOMAIN_MIN, DOMAIN_MAX, 1],
            z_range=[
                0,
                self.linear_max,
                self.linear_max / 4,
            ],
            x_length=6.4,
            y_length=6.4,
            z_length=4.4,
            axis_config={
                "stroke_width": 1.6,
                "include_ticks": False,
            },
        ).shift(DOWN * 0.25)

        db_axes = ThreeDAxes(
            x_range=[DOMAIN_MIN, DOMAIN_MAX, 1],
            y_range=[DOMAIN_MIN, DOMAIN_MAX, 1],
            z_range=[DB_MIN, DB_MAX, 10],
            x_length=6.4,
            y_length=6.4,
            z_length=4.4,
            axis_config={
                "stroke_width": 1.6,
                "include_ticks": False,
            },
        ).shift(DOWN * 0.25)

        re_label = MathTex(r"\Re(s)").scale(0.55)
        re_label.next_to(
            linear_axes.x_axis.get_end(),
            RIGHT,
            buff=0.06,
        )

        im_label = MathTex(r"\Im(s)").scale(0.55)
        im_label.next_to(
            linear_axes.y_axis.get_end(),
            UP,
            buff=0.06,
        )

        linear_z_label = MathTex(
            r"|H(s)|"
        ).scale(0.57)

        linear_z_label.next_to(
            linear_axes.z_axis.get_end(),
            UP,
            buff=0.08,
        )

        db_z_label = MathTex(
            r"20\log_{10}|H(s)|"
        ).scale(0.50)

        db_z_label.next_to(
            db_axes.z_axis.get_end(),
            UP,
            buff=0.08,
        )

        # ---------------------------------------------------------------
        # Fixed title and formula
        # ---------------------------------------------------------------

        title = Tex(self.scene_title).scale(0.64)
        title.to_corner(UL, buff=0.22)

        formula = MathTex(self.formula).scale(0.56)
        formula.next_to(
            title,
            DOWN,
            aligned_edge=LEFT,
            buff=0.10,
        )

        legend = self.make_legend()
        legend.to_corner(UR, buff=0.28)

        linear_scale_caption = Tex(
            "linear magnitude"
        ).scale(0.48)

        linear_scale_caption.next_to(
            legend,
            DOWN,
            aligned_edge=RIGHT,
            buff=0.12,
        )

        db_scale_caption = Tex(
            "magnitude in decibels"
        ).scale(0.48)

        db_scale_caption.move_to(
            linear_scale_caption
        )

        title.set_opacity(0)
        formula.set_opacity(0)
        legend.set_opacity(0)
        linear_scale_caption.set_opacity(0)
        db_scale_caption.set_opacity(0)

        self.add_fixed_in_frame_mobjects(
            title,
            formula,
            legend,
            linear_scale_caption,
            db_scale_caption,
        )

        # ---------------------------------------------------------------
        # Reference complex plane
        # ---------------------------------------------------------------

        reference_plane = Surface(
            lambda sigma, omega: linear_axes.c2p(
                sigma,
                omega,
                0,
            ),
            u_range=[DOMAIN_MIN, DOMAIN_MAX],
            v_range=[DOMAIN_MIN, DOMAIN_MAX],
            resolution=(12, 12),
            fill_opacity=0.06,
            stroke_color=GREY_B,
            stroke_width=0.45,
        )

        reference_plane.set_fill_by_checkerboard(
            GREY_E,
            GREY_D,
            opacity=0.07,
        )

        # ---------------------------------------------------------------
        # Linear-magnitude surface
        # ---------------------------------------------------------------

        linear_surface = Surface(
            lambda sigma, omega: linear_axes.c2p(
                sigma,
                omega,
                self.linear_magnitude_clipped(
                    sigma,
                    omega,
                ),
            ),
            u_range=[DOMAIN_MIN, DOMAIN_MAX],
            v_range=[DOMAIN_MIN, DOMAIN_MAX],
            resolution=(
                SURFACE_RESOLUTION,
                SURFACE_RESOLUTION,
            ),
            fill_opacity=0.76,
            stroke_color=GREY_B,
            stroke_width=0.25,
        )

        linear_surface.set_fill_by_checkerboard(
            SURFACE_COLOR_1,
            SURFACE_COLOR_2,
            opacity=0.76,
        )

        # ---------------------------------------------------------------
        # Logarithmic-magnitude surface
        # ---------------------------------------------------------------

        db_surface = Surface(
            lambda sigma, omega: db_axes.c2p(
                sigma,
                omega,
                self.db_magnitude_clipped(
                    sigma,
                    omega,
                ),
            ),
            u_range=[DOMAIN_MIN, DOMAIN_MAX],
            v_range=[DOMAIN_MIN, DOMAIN_MAX],
            resolution=(
                SURFACE_RESOLUTION,
                SURFACE_RESOLUTION,
            ),
            fill_opacity=0.76,
            stroke_color=GREY_B,
            stroke_width=0.25,
        )

        db_surface.set_fill_by_checkerboard(
            SURFACE_COLOR_1,
            SURFACE_COLOR_2,
            opacity=0.76,
        )

        zero_markers = VGroup(
            *[
                self.zero_marker(linear_axes, zero)
                for zero in self.zeros
            ]
        )

        pole_markers = VGroup(
            *[
                self.pole_marker(linear_axes, pole)
                for pole in self.poles
            ]
        )

        # ---------------------------------------------------------------
        # 1. Pole-zero map
        # ---------------------------------------------------------------

        self.set_camera_orientation(
            phi=0 * DEGREES,
            theta=-90 * DEGREES,
            zoom=0.88,
        )

        self.play(
            title.animate.set_opacity(1),
            formula.animate.set_opacity(1),
            legend.animate.set_opacity(1),
            run_time=1.0,
        )

        self.play(
            Create(linear_axes.x_axis),
            Create(linear_axes.y_axis),
            Create(reference_plane),
            run_time=1.5,
        )

        self.play(
            FadeIn(re_label, im_label),
            run_time=0.6,
        )

        self.add_fixed_orientation_mobjects(
            re_label,
            im_label,
        )

        if self.zeros:
            self.play(
                Create(zero_markers),
                run_time=1.0,
            )

        if self.poles:
            self.play(
                Create(pole_markers),
                run_time=1.0,
            )

        self.wait(0.8)

        # ---------------------------------------------------------------
        # 2. Linear magnitude
        # ---------------------------------------------------------------

        self.move_camera(
            phi=64 * DEGREES,
            theta=-50 * DEGREES,
            zoom=0.82,
            added_anims=[
                Create(linear_axes.z_axis),
            ],
            run_time=2.5,
        )

        self.play(
            FadeIn(linear_z_label),
            linear_scale_caption.animate.set_opacity(1),
            run_time=0.7,
        )

        self.add_fixed_orientation_mobjects(
            linear_z_label
        )

        linear_formula = MathTex(
            r"|H(s)|=|K|\,"
            r"\frac{\prod_i|s-z_i|}"
            r"{\prod_i|s-p_i|}"
        ).scale(0.54)

        linear_formula.to_edge(DOWN, buff=0.14)
        linear_formula.set_opacity(0)

        self.add_fixed_in_frame_mobjects(
            linear_formula
        )

        self.play(
            Create(linear_surface),
            linear_formula.animate.set_opacity(1),
            run_time=3.0,
        )

        self.wait(1.0)

        # ---------------------------------------------------------------
        # 3. Distance interpretation
        # ---------------------------------------------------------------

        sigma = ValueTracker(
            self.sample_start.real
        )

        omega = ValueTracker(
            self.sample_start.imag
        )

        sample_on_plane = always_redraw(
            lambda: Dot3D(
                linear_axes.c2p(
                    sigma.get_value(),
                    omega.get_value(),
                    0,
                ),
                radius=0.055,
                color=SAMPLE_COLOR,
            )
        )

        sample_on_surface = always_redraw(
            lambda: Dot3D(
                linear_axes.c2p(
                    sigma.get_value(),
                    omega.get_value(),
                    self.linear_magnitude_clipped(
                        sigma.get_value(),
                        omega.get_value(),
                    ),
                ),
                radius=0.065,
                color=SAMPLE_COLOR,
            )
        )

        vertical_readoff = always_redraw(
            lambda: DashedLine(
                linear_axes.c2p(
                    sigma.get_value(),
                    omega.get_value(),
                    0,
                ),
                linear_axes.c2p(
                    sigma.get_value(),
                    omega.get_value(),
                    self.linear_magnitude_clipped(
                        sigma.get_value(),
                        omega.get_value(),
                    ),
                ),
                color=SAMPLE_COLOR,
                stroke_width=2.2,
                dash_length=0.09,
            )
        )

        zero_distances = VGroup(
            *[
                always_redraw(
                    lambda zero=zero: Line(
                        linear_axes.c2p(
                            sigma.get_value(),
                            omega.get_value(),
                            0,
                        ),
                        linear_axes.c2p(
                            zero.real,
                            zero.imag,
                            0,
                        ),
                        color=ZERO_COLOR,
                        stroke_width=2.8,
                    )
                )
                for zero in self.zeros
            ]
        )

        pole_distances = VGroup(
            *[
                always_redraw(
                    lambda pole=pole: Line(
                        linear_axes.c2p(
                            sigma.get_value(),
                            omega.get_value(),
                            0,
                        ),
                        linear_axes.c2p(
                            pole.real,
                            pole.imag,
                            0,
                        ),
                        color=POLE_COLOR,
                        stroke_width=2.8,
                    )
                )
                for pole in self.poles
            ]
        )

        self.play(
            FadeIn(
                sample_on_plane,
                sample_on_surface,
                vertical_readoff,
                zero_distances,
                pole_distances,
            ),
            run_time=1.0,
        )

        target = self.target_sample()

        self.play(
            sigma.animate.set_value(target.real),
            omega.animate.set_value(target.imag),
            run_time=3.2,
            rate_func=smooth,
        )

        self.wait(0.8)

        self.play(
            FadeOut(
                sample_on_plane,
                sample_on_surface,
                vertical_readoff,
                zero_distances,
                pole_distances,
            ),
            run_time=0.8,
        )

        # ---------------------------------------------------------------
        # 4. Transform to decibels
        # ---------------------------------------------------------------

        conversion_formula = MathTex(
            r"|H(s)|",
            r"\quad\longmapsto\quad",
            r"20\log_{10}|H(s)|"
        ).scale(0.60)

        conversion_formula.to_edge(
            DOWN,
            buff=0.14,
        )

        conversion_formula[0].set_color(RED_C)
        conversion_formula[2].set_color(YELLOW_C)
        conversion_formula.set_opacity(0)

        self.add_fixed_in_frame_mobjects(
            conversion_formula
        )

        self.play(
            linear_formula.animate.set_opacity(0),
            conversion_formula.animate.set_opacity(1),
            run_time=0.9,
        )

        self.wait(0.5)

        self.play(
            ReplacementTransform(
                linear_surface,
                db_surface,
            ),
            ReplacementTransform(
                linear_axes.z_axis,
                db_axes.z_axis,
            ),
            ReplacementTransform(
                linear_z_label,
                db_z_label,
            ),
            linear_scale_caption.animate.set_opacity(0),
            db_scale_caption.animate.set_opacity(1),
            run_time=4.0,
            rate_func=smooth,
        )

        self.add_fixed_orientation_mobjects(
            db_z_label
        )

        self.wait(0.8)

        # ---------------------------------------------------------------
        # 5. Explain the limiting values
        # ---------------------------------------------------------------

        if self.zeros and not self.poles:
            limiting_statement = MathTex(
                r"s\to z_i:",
                r"\qquad |H(s)|\to0",
                r"\qquad\Longrightarrow\qquad",
                r"20\log_{10}|H(s)|\to-\infty"
            )

            limiting_statement[0].set_color(
                ZERO_COLOR
            )
            limiting_statement[3].set_color(
                ZERO_COLOR
            )

        elif self.poles and not self.zeros:
            limiting_statement = MathTex(
                r"s\to p_i:",
                r"\qquad |H(s)|\to+\infty",
                r"\qquad\Longrightarrow\qquad",
                r"20\log_{10}|H(s)|\to+\infty"
            )

            limiting_statement[0].set_color(
                POLE_COLOR
            )
            limiting_statement[3].set_color(
                POLE_COLOR
            )

        else:
            limiting_statement = MathTex(
                r"z_i:\ -\infty\ \mathrm{dB}",
                r"\qquad\qquad",
                r"p_i:\ +\infty\ \mathrm{dB}"
            )

            limiting_statement[0].set_color(
                ZERO_COLOR
            )
            limiting_statement[2].set_color(
                POLE_COLOR
            )

        limiting_statement.scale(0.52)
        limiting_statement.to_edge(
            DOWN,
            buff=0.14,
        )
        limiting_statement.set_opacity(0)

        self.add_fixed_in_frame_mobjects(
            limiting_statement
        )

        self.play(
            conversion_formula.animate.set_opacity(0),
            limiting_statement.animate.set_opacity(1),
            run_time=0.9,
        )

        self.wait(1.3)

        # ---------------------------------------------------------------
        # 6. Imaginary-axis slice
        # ---------------------------------------------------------------

        imaginary_axis_plane = Surface(
            lambda omega, db_value: db_axes.c2p(
                0,
                omega,
                db_value,
            ),
            u_range=[DOMAIN_MIN, DOMAIN_MAX],
            v_range=[DB_MIN, DB_MAX],
            resolution=(2, 2),
            fill_color=SLICE_COLOR,
            fill_opacity=0.10,
            stroke_color=SLICE_COLOR,
            stroke_width=0.8,
        )

        frequency_response_slice = ParametricFunction(
            lambda omega: db_axes.c2p(
                0,
                omega,
                self.db_magnitude_clipped(
                    0,
                    omega,
                ),
            ),
            t_range=[
                DOMAIN_MIN,
                DOMAIN_MAX,
                0.025,
            ],
            color=SLICE_COLOR,
            stroke_width=5,
        )

        slice_statement = MathTex(
            r"\Re(s)=0:",
            r"\qquad s=\mathrm{j}\omega",
            r"\qquad\Longrightarrow\qquad",
            r"20\log_{10}|H(\mathrm{j}\omega)|"
        ).scale(0.52)

        slice_statement.to_edge(
            DOWN,
            buff=0.14,
        )

        slice_statement[3].set_color(
            SLICE_COLOR
        )

        slice_statement.set_opacity(0)

        self.add_fixed_in_frame_mobjects(
            slice_statement
        )

        self.play(
            limiting_statement.animate.set_opacity(0),
            slice_statement.animate.set_opacity(1),
            FadeIn(imaginary_axis_plane),
            run_time=1.2,
        )

        self.play(
            Create(frequency_response_slice),
            run_time=2.2,
        )

        self.wait(0.8)

        # ---------------------------------------------------------------
        # 7. Brief inspection rotation
        # ---------------------------------------------------------------

        self.begin_ambient_camera_rotation(
            rate=0.06,
            about="theta",
        )

        self.wait(3.5)

        self.stop_ambient_camera_rotation()

        # ---------------------------------------------------------------
        # 8. Final view emphasizing the jω-plane intersection
        # ---------------------------------------------------------------

        self.move_camera(
            phi=74 * DEGREES,
            theta=-15 * DEGREES,
            zoom=0.88,
            added_anims=[
                frequency_response_slice.animate.set_stroke(
                    width=7
                ),
                imaginary_axis_plane.animate.set_fill(
                    opacity=0.16
                ),
                db_surface.animate.set_opacity(0.62),
            ],
            run_time=3.0,
            rate_func=smooth,
        )

        self.wait(2.5)


# ---------------------------------------------------------------------------
# Individual scenes
# ---------------------------------------------------------------------------

class ModulusGraphRealZero(
    MagnitudeLandscapeMixin,
    ThreeDScene,
):

    scene_title = "Magnitude landscape of a real zero"

    formula = r"H(s)=s+1"

    zeros = (
        -1.0 + 0.0j,
    )

    poles = ()

    linear_max = 6.0


class ModulusGraphComplexConjugateZeros(
    MagnitudeLandscapeMixin,
    ThreeDScene,
):

    scene_title = (
        "Magnitude landscape of conjugate zeros"
    )

    formula = (
        r"H(s)="
        r"(s+1-\mathrm{j})"
        r"(s+1+\mathrm{j})"
    )

    zeros = (
        -1.0 + 1.0j,
        -1.0 - 1.0j,
    )

    poles = ()

    linear_max = 20.0


class ModulusGraphRealPole(
    MagnitudeLandscapeMixin,
    ThreeDScene,
):

    scene_title = "Magnitude landscape of a real pole"

    formula = (
        r"H(s)=\frac{1}{s+1}"
    )

    zeros = ()

    poles = (
        -1.0 + 0.0j,
    )

    linear_max = 5.0


class ModulusGraphComplexConjugatePoles(
    MagnitudeLandscapeMixin,
    ThreeDScene,
):

    scene_title = (
        "Magnitude landscape of conjugate poles"
    )

    formula = (
        r"H(s)="
        r"\frac{1}{"
        r"(s+1-1.5\mathrm{j})"
        r"(s+1+1.5\mathrm{j})"
        r"}"
    )

    zeros = ()

    poles = (
        -1.0 + 1.5j,
        -1.0 - 1.5j,
    )

    linear_max = 4.0


class ModulusGraphGenericTF(
    MagnitudeLandscapeMixin,
    ThreeDScene,
):

    scene_title = (
        "Magnitude landscape of a transfer function"
    )

    formula = (
        r"H(s)="
        r"\frac{"
        r"(s+1-0.65\mathrm{j})"
        r"(s+1+0.65\mathrm{j})"
        r"}{"
        r"(s+2)"
        r"(s+0.5-1.8\mathrm{j})"
        r"(s+0.5+1.8\mathrm{j})"
        r"}"
    )

    zeros = (
        -1.0 + 0.65j,
        -1.0 - 0.65j,
    )

    poles = (
        -2.0 + 0.0j,
        -0.5 + 1.8j,
        -0.5 - 1.8j,
    )

    linear_max = 6.0


